#include "playback.h"
#include "trajectory_display.h"
#include <fstream>
#include <iostream>
#include <chrono>
#include <iomanip>
using namespace rs3d;
namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
double percentile(std::vector<double>values,double fraction){std::sort(values.begin(),values.end());return values[size_t(fraction*(values.size()-1))];}
void rotations(){Snapshot a,b;a.time=0;b.time=1;a.center={1,2,3};b.center={3,4,5};a.shapeOrigin={2,3,4};b.shapeOrigin={4,5,6};a.rotation={1,0,0,0};b.rotation={-1,0,0,0};a.barrier.enabled=b.barrier.enabled=true;a.barrier.center={5,6,7};b.barrier.center={7,8,9};a.barrier.rotation=Quaternion::fromAxisAngle({0,0,1},.1);b.barrier.rotation=Quaternion::fromAxisAngle({0,0,1},pi-.01);a.contacts.barrier=0;b.contacts.barrier=1;
    auto mid=interpolateMotion(a,b,.5);check(norm(mid.center-Vec3{2,3,4})==0&&norm(mid.shapeOrigin-Vec3{3,4,5})==0&&mid.rotation.w==1&&mid.contacts.barrier==0&&norm(mid.barrier.center-Vec3{6,7,8})==0,"playback interpolation mismatch");check(interpolateMotion(a,b,1).rotation.w==-1&&interpolateMotion(a,b,-10).time==0&&interpolateMotion(a,b,10).time==1,"exact frame or clamping changed source");b.time=0;check(interpolateMotion(a,b,0).time==0,"zero duration");auto q=displaySlerp({},Quaternion::fromAxisAngle({0,1,0},pi-1e-9),.5);check(std::abs(q.w-std::sqrt(.5))<1e-8&&std::isfinite(q.matrix()(0,0)),"near-180 SLERP");std::cout<<"R3 exact endpoints, zero duration, q/-q, shortest arc and dynamic barrier PASS\n";
}
std::shared_ptr<const MotionDirectory> synthetic(const std::filesystem::path&path,std::uint64_t count,int intervals,double dt){std::filesystem::create_directories(path);std::map<std::string,std::ofstream>files;auto write=[&](const std::string&name,const std::string&bytes){auto&f=files[name];if(!f.is_open())f.open(path/name,std::ios::binary|std::ios::trunc);f.write(bytes.data(),std::streamsize(bytes.size()));check(bool(f),"synthetic archive write failed");};auto flush=[&](const std::string&name){files.at(name).flush();check(bool(files.at(name)),"synthetic flush failed");};MotionArchiveWriter writer(std::make_shared<ArchiveLocation>(path),count,write,flush);
    for(std::uint64_t id=1;id<=count;++id){std::vector<MotionFrame>block;block.reserve(motionBlockFrames);for(int i=0;i<=intervals;++i){MotionFrame f;f.step=std::uint64_t(std::llround(i*dt/.002));auto&s=f.snapshot;s.time=i*dt;s.center={double(id),s.time,s.time*s.time};s.shapeOrigin=s.center+Vec3{.01,.02,.03};s.rotation=Quaternion::fromAxisAngle({0,0,1},s.time*.01);s.barrier.enabled=true;s.barrier.elastic=true;s.barrier.center={20+s.time,.2,.5};s.barrier.displacement=s.time;s.barrier.velocity=1;s.reason=i==intervals?StopReason::resting:StopReason::running;block.push_back(f);if(block.size()==motionBlockFrames){writer.append(id,block);block.clear();}}if(!block.empty())writer.append(id,block);writer.status(id,"resting");}for(auto&f:files)f.second.close();return readMotionDirectory(path,count);
}
void reads(std::shared_ptr<const MotionDirectory>d,bool performance){MotionBlockCache cache(256*1024*1024);std::vector<double>cold,hot;std::uint64_t totalFrames=0;for(const auto&t:d->trials){totalFrames+=t->frames;auto result=cache.sample(*d,t->id,t->lastTime*.501);check(result.available&&result.trialId==t->id&&result.snapshot.center.x==double(t->id),"trial selection data crossed trial boundary");cold.push_back(result.loadMilliseconds);for(int i=0;i<5;++i){result=cache.sample(*d,t->id,t->lastTime*.501+i*.0001);check(result.available,"cached seek failed");hot.push_back(result.loadMilliseconds);}}
    auto one=cache.sample(*d,1,0);auto last=cache.sample(*d,1,d->trials[0]->lastTime);auto backward=cache.sample(*d,1,.003);check(one.snapshot.time==0&&last.snapshot.reason==StopReason::resting&&backward.available,"reverse/final seek failed");check(cache.peakBytes()<=256*1024*1024+motionBlockFrames*sizeof(MotionFrame),"cache exceeds cap plus one block");
    PlaybackReader reader(1024*1024);std::uint64_t latest=0;for(int i=0;i<500;++i)latest=reader.request(d,(i%int(d->trials.size()))+1,.001*i);auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);std::shared_ptr<const PlaybackSample> published;do{published=reader.latest();if(published&&published->request==latest)break;std::this_thread::sleep_for(std::chrono::milliseconds(1));}while(std::chrono::steady_clock::now()<deadline);check(published&&published->request==latest&&published->available,"stale async seek replaced latest request");reader.invalidate();check(!reader.latest(),"invalidated seek result remained visible");
    std::cout<<std::setprecision(12)<<"archive="<<d->location->path().u8string()<<" trials_selected="<<d->trials.size()<<" frames="<<totalFrames<<" motion_bytes="<<std::filesystem::file_size(d->location->path()/"motion.bin")<<" decoded_cache_peak="<<cache.peakBytes()<<" index_block_bytes=";size_t index=0;for(const auto&t:d->trials)index+=sizeof(MotionTrial)+t->blocks.capacity()*sizeof(MotionBlock);std::cout<<index<<" first_block_p95_ms="<<percentile(cold,.95)<<" first_block_max_ms="<<*std::max_element(cold.begin(),cold.end())<<" cache_hit_p95_ms="<<percentile(hot,.95)<<'\n';if(performance){check(percentile(hot,.95)<=100,"P1 cache-hit P95 exceeds 100ms");check(*std::max_element(cold.begin(),cold.end())<=500,"P1 first selected block exceeds 500ms");}
}
void allTrajectories(std::shared_ptr<const MotionDirectory>d){TrajectoryArchiveReader reader;reader.request(d,2000000);std::shared_ptr<const TrajectoryLoadView> loaded;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(120);do{loaded=reader.view();if(loaded&&loaded->finished)break;std::this_thread::sleep_for(std::chrono::milliseconds(2));}while(std::chrono::steady_clock::now()<deadline);check(loaded&&loaded->finished&&loaded->error.empty(),"all-trial display did not finish");size_t vertices=0;for(size_t i=0;i<d->trials.size();++i){const auto&t=loaded->trajectories[i];check(t&&t->trialId==i+1&&t->points.front().time==d->trials[i]->firstTime&&t->points.back().time==d->trials[i]->lastTime&&t->status==StopReason::resting,"display dropped a trial/start/end/status");vertices+=t->points.size();}check(vertices<=2000000,"global display budget exceeded");std::cout<<"H3 full display N="<<d->trials.size()<<" first/last all IDs retained vertices="<<vertices<<" PASS\n";}
void simplification(){std::vector<TimedPosition>source;for(int i=0;i<30001;++i)source.push_back({i*.002,{i*.002,std::abs(i-15000)*.001,0}});auto a=simplifyTrajectory(1,source,StopReason::cancelled,2000),b=simplifyTrajectory(1,source,StopReason::cancelled,2000);check(a->points.size()<=2000&&a->points.front().time==0&&a->points.back().time==60&&a->points.size()==b->points.size()&&a->status==StopReason::cancelled,"long trajectory truncated start or status");bool turn=false;for(size_t i=0;i<a->points.size();++i){turn|=a->points[i].time==30;check(a->points[i].time==b->points[i].time,"simplification nondeterministic");}check(turn,"important trajectory turn removed");std::cout<<"H3 deterministic 30001-point path first/last/turn and cancelled status PASS\n";}

}
int main(int argc,char**argv){try{std::cout<<std::unitbuf;rotations();bool performance=argc>1&&std::string(argv[1])=="--performance";auto root=argc>2?std::filesystem::u8path(argv[2]):std::filesystem::temp_directory_path()/"rs3d_playback";if(performance){auto explicitHz=synthetic(root/"explicit_100hz",1000,6000,.01);reads(explicitHz,true);allTrajectories(explicitHz);auto autoHz=synthetic(root/"auto_50hz",1000,3000,.02);reads(autoHz,true);allTrajectories(autoHz);}else{reads(synthetic(root,4,600,.01),false);for(int n:{2,3,1000})allTrajectories(synthetic(root/("trials_"+std::to_string(n)),n,n<1000?2500:8,.01));}simplification();std::cout<<"PASS read-only playback/cache/async request ordering\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
